/**
 * Typecheck `ts` fences in our own documentation against built `@matter/*` declarations (ISS-894).
 *
 * 口径（老板 2026-11-20 拍板）：
 *   · 射程 = 自有 API 示例：根 README.md、docs 下所有 md、packages 两层包目录下的 md，
 *     排除 `docs/dsh-wiki/`（DSH 抄本）、`docs/memory/`（DSH 语录型过程记录）、`*.zh.md`（配对副本）
 *     与 `<!-- Generated by ... -->` 头注文件（生成物由各自 owner 判据校验）。
 *   · 绝对判据：射程内 fence 零 TS 错（tsc --noEmit 口径）；0 语料 ⇒ unjudged，不冒绿。
 *   · ignore 必须带理由（`ts ignore-check: <理由>`）；无理由 ⇒ 红。比例只打印、不判红。
 *   · 三态：passed / failed / unjudged（缺 lib 产物 ⇒ no-build，0 语料 ⇒ no-corpus）。
 *   · 零新依赖：行扫描器提 fence —— 本语料 0 个 HTML 注释内 fence，与 mdast 等价（调研实测）。
 *
 * 裁剪自 DSH 5 模块共 927 行（其中 scripts/doc-typecheck.ts 单文件 255 行），本实现保留核心 ~204 行：
 * 搬 extractBlocks / compileBlocksStandalone / remapBlockPaths / 主流程；砍 3 类 catalog kind、
 * paired-markdown-derivatives、frozen guide、build-coordinated 双模式（只留 standalone）。
 */
import { execFileSync } from "node:child_process"
import { globSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { isMain, runGate, unjudged, type Finding, type GateResult } from "../lib/gate-runtime.ts"

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..")
const GATE = "doc-typecheck"
const GENERATED_RE = /^<!--\s*Generated by\b/
const MARKDOWN_GLOBS = ["README.md", "docs/**/*.md", "packages/*/*/*.md"] as const

/** One fenced code block located by the line scanner. */
export interface Fence {
  /** 1-based line of the opening fence. */
  line: number
  /** Full info string of the opening fence (e.g. `ts ignore-check: why`). */
  info: string
  /** Block body without the fence delimiters. */
  code: string
}

/**
 * Extract every fenced code block with a line scanner — no mdast dependency.
 * @param source - Markdown source to scan.
 * @returns fences in document order with opening line, info string, and body.
 */
export function scanFences(source: string): Fence[] {
  const lines = source.split("\n")
  const out: Fence[] = []
  let cur: { line: number; info: string; body: string[]; ch: string; len: number } | undefined
  for (let i = 0; i < lines.length; i++) {
    const m = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(lines[i])
    if (!cur) {
      if (m && !m[2].includes(m[1][0])) {
        cur = { line: i + 1, info: m[2].trim(), body: [], ch: m[1][0], len: m[1].length }
      }
    } else if (m && m[1][0] === cur.ch && m[1].length >= cur.len && m[2].trim() === "") {
      out.push({ line: cur.line, info: cur.info, code: cur.body.join("\n") })
      cur = undefined
    } else {
      cur.body.push(lines[i])
    }
  }
  // mdast silently closes an unterminated fence at EOF; do the same.
  if (cur) out.push({ line: cur.line, info: cur.info, code: cur.body.join("\n") })
  return out
}

/** A tracked fence: either compile-checked `ts` or a reason-bearing ignore. */
export interface Block extends Fence {
  /** Repo-relative Markdown file owning this fence. */
  file: string
  kind: "check" | "ignore"
  /** Non-empty reason on an `ignore` fence. */
  reason?: string
}

/** An `ignore-check` fence with no reason — a red finding, not an opt-out. */
export interface BadIgnore {
  file: string
  line: number
  info: string
}

/** What {@link collectBlocks} found, including the file-level generated skip count. */
export interface ScanResult {
  blocks: Block[]
  badIgnores: BadIgnore[]
  skippedGenerated: number
}

/**
 * Whether a repo-relative Markdown path belongs to our own API-example corpus.
 * @param rel - forward-slash repo-relative path.
 */
export function isInScope(rel: string): boolean {
  if (rel.startsWith("docs/dsh-wiki/") || rel.startsWith("docs/memory/")) return false
  if (rel.endsWith(".zh.md")) return false
  if (rel === "README.md" || rel.startsWith("docs/")) return true
  return /^packages\/[^/]+\/[^/]+\/[^/]+\.md$/.test(rel)
}

/** Whether a file is a generated catalog (skipped wholesale by its own owner gate). */
export function isGeneratedHeader(content: string): boolean {
  return GENERATED_RE.test(content)
}

/**
 * Collect tracked fences from `(rel, content)` pairs, applying scope and generated-skip rules.
 * @param files - repo-relative Markdown paths.
 * @param read - content reader for one path.
 */
export function collectBlocks(files: readonly string[], read: (rel: string) => string): ScanResult {
  const blocks: Block[] = []
  const badIgnores: BadIgnore[] = []
  let skippedGenerated = 0
  for (const rel of files) {
    if (!isInScope(rel)) continue
    const content = read(rel)
    if (isGeneratedHeader(content)) {
      skippedGenerated += 1
      continue
    }
    for (const fence of scanFences(content)) {
      if (fence.info === "ts") {
        blocks.push({ ...fence, file: rel, kind: "check" })
      } else if (fence.info === "ts ignore-check" || fence.info.startsWith("ts ignore-check:")) {
        const reason = fence.info.startsWith("ts ignore-check:") ? fence.info.slice("ts ignore-check:".length).trim() : ""
        if (reason === "") badIgnores.push({ file: rel, line: fence.line, info: fence.info })
        else blocks.push({ ...fence, file: rel, kind: "ignore", reason })
      }
    }
  }
  return { blocks, badIgnores, skippedGenerated }
}

/** A compiler diagnostic mapped back to its owning Markdown fence. */
export interface CompileError {
  file: string
  line: number
  column: number
  message: string
}

/** Three outcomes of the standalone compile: no build, clean, or errors. */
export type CompileOutcome =
  | { kind: "no-build"; detail: string }
  | { kind: "compiled" }
  | { kind: "errors"; errors: CompileError[] }

/** Injectable compiler — the spec feeds a controlled outcome without touching the repo. */
export type CompileFn = (blocks: readonly Block[]) => CompileOutcome

/** Pure-function input for {@link judge}. */
export interface JudgeInput {
  blocks: readonly Block[]
  badIgnores: readonly BadIgnore[]
  skippedGenerated: number
  compile: CompileFn
}

/**
 * The gate's pure decision. Order matters: no-corpus first (never green on empty),
 * then no-reason ignore (a quality violation independent of compilation), then build, then TS errors.
 * @param input - collected fences + injected compiler.
 */
export function judge(input: JudgeInput): GateResult {
  const all = input.blocks.length + input.badIgnores.length
  if (all === 0) {
    return unjudged(GATE, "no-corpus", "射程内 0 个 ts fence ⇒ 判不了「示例零 TS 错」（空语料不是绿）")
  }
  const findings: Finding[] = input.badIgnores.map((b) => ({
    file: b.file,
    line: b.line,
    detail: `无理由 ignore（\`${b.info}\`）：期望 \`ts ignore-check: <理由>\` 写明为什么跳过；实际没有理由 ⇒ 意图不显式`,
  }))
  if (input.badIgnores.length > 0) return { gate: GATE, status: "failed", findings }

  const checked = input.blocks.filter((b) => b.kind === "check")
  const ignored = input.blocks.filter((b) => b.kind === "ignore")
  const outcome = input.compile(checked)
  if (outcome.kind === "no-build") return unjudged(GATE, "no-build", outcome.detail)
  if (outcome.kind === "errors") {
    for (const e of outcome.errors) {
      findings.push({
        file: e.file,
        line: e.line,
        detail: `期望该 fence 零 TS 错；实际 ${e.message}（列 ${e.column}）`,
      })
    }
    return { gate: GATE, status: "failed", findings }
  }

  const denom = checked.length + ignored.length
  // Ratio is reported, never judged (no count ratchet).
  console.log(`doc-typecheck: ${checked.length} block(s) compiled, ${ignored.length} ignored (${denom ? ((ignored.length / denom) * 100).toFixed(0) : "0"}% opt-out), skipped ${input.skippedGenerated} generated file(s).`)
  return { gate: GATE, status: "passed", findings: [] }
}

/**
 * Map virtual `block-N.ts(line,col)` diagnostics back to Markdown `file:line`.
 * @param output - raw tsc output.
 * @param blocks - the checked blocks, indexed by virtual file number.
 */
export function remapBlockPaths(output: string, blocks: readonly Block[]): string {
  return output.replace(/(?:[^\s:()]*[/\\])?block-(\d+)\.ts\((\d+),(\d+)\)/g, (_m, i: string, l: string, c: string) => {
    const block = blocks[Number(i)]
    if (!block) return `block-${i}.ts(${l},${c})`
    return `${block.file}:${block.line + Number(l)}:${c}`
  })
}

/** Parse remapped tsc output into structured diagnostics (file:line:col: TSxxxx: msg). */
function parseDiagnostics(output: string): CompileError[] {
  const errors: CompileError[] = []
  const re = /^(.+?):(\d+):(\d+): error (TS\d+: .*)$/gm
  for (const m of output.matchAll(re)) {
    errors.push({ file: m[1], line: Number(m[2]), column: Number(m[3]), message: m[4] })
  }
  return errors
}

/**
 * Standalone compile through a dedicated tsconfig whose `@matter/*` paths point at
 * the built `lib/types` of each two-level package. Missing lib/tsconfig ⇒ no-build (unjudged, not red).
 * @param blocks - checked fences; each becomes a virtual `block-N.ts`.
 */
export function compileStandalone(blocks: readonly Block[]): CompileOutcome {
  // 100% 带理由 opt-out ⇒ checked 为空、没有可编译的输入。tsc -p 会报 TS18003「No inputs were found」
  // （加 TS5101），那不是示例的类型错，判红会把「全部显式跳过」误伤成失败。空输入直接成功，不调 tsc。
  if (blocks.length === 0) return { kind: "compiled" }
  const libDirs: string[] = []
  for (const pkg of globSync("packages/*/*/package.json", { cwd: REPO })) {
    const dir = path.dirname(pkg)
    if (!globSync(`${dir}/lib/types/index.d.ts`, { cwd: REPO }).length) continue
    const name = (JSON.parse(readFileSync(path.join(REPO, pkg), "utf8")) as { name?: string }).name
    if (name) libDirs.push([name, dir].join("\0"))
  }
  if (libDirs.length === 0) {
    return { kind: "no-build", detail: "packages/*/*/lib/types 不存在（未构建）：判不了「示例零 TS 错」，不判红" }
  }
  const paths = Object.fromEntries(libDirs.map((entry) => {
    const [name, dir] = entry.split("\0")
    return [name, [dir.replaceAll("\\", "/") + "/lib/types"]]
  }))
  const tmp = mkdtempSync(path.join(REPO, ".doc-typecheck-"))
  try {
    writeFileSync(path.join(tmp, "tsconfig.json"), JSON.stringify({
      compilerOptions: {
        target: "ES2022", module: "NodeNext", moduleResolution: "NodeNext",
        strict: true, noEmit: true, skipLibCheck: true,
        noUnusedLocals: false, noUnusedParameters: false,
        baseUrl: REPO, paths,
      },
      include: ["block-*.ts"],
    }))
    for (const [index, block] of blocks.entries()) {
      writeFileSync(path.join(tmp, `block-${index}.ts`), block.code.endsWith("\n") ? block.code : `${block.code}\n`)
    }
    let raw = ""
    try {
      execFileSync(process.execPath, ["node_modules/typescript/bin/tsc", "-p", path.join(tmp, "tsconfig.json"), "--pretty", "false"], {
        cwd: REPO, stdio: "pipe",
      })
      return { kind: "compiled" }
    } catch (error: unknown) {
      const failed = error as { stdout?: Buffer; stderr?: Buffer }
      raw = `${failed.stdout?.toString() ?? ""}${failed.stderr?.toString() ?? ""}`
    }
    const errors = parseDiagnostics(remapBlockPaths(raw, blocks))
    return errors.length > 0
      ? { kind: "errors", errors }
      : { kind: "errors", errors: [{ file: "(tsc)", line: 0, column: 0, message: raw.trim().slice(0, 400) || "tsc 非零退出但无结构化诊断" }] }
  } finally {
    rmSync(tmp, { recursive: true, force: true })
  }
}

/** Scan the real repository: glob, scope filter, generated-skip, fence extraction. */
function scanRepo(): ScanResult {
  const files: string[] = []
  for (const pattern of MARKDOWN_GLOBS) {
    for (const match of globSync(pattern, { cwd: REPO })) files.push(match.replaceAll("\\", "/"))
  }
  return collectBlocks(files.sort(), (rel) => readFileSync(path.join(REPO, rel), "utf8"))
}

if (isMain(import.meta.url)) {
  runGate({ name: GATE, main: () => judge({ ...scanRepo(), compile: compileStandalone }) })
    .then((code) => { process.exitCode = code })
    .catch((e: unknown) => {
      console.error(`✗ ${GATE}: ${(e as Error).message}`)
      process.exitCode = 2
    })
}
